//! Gemma — the subid → tag → OpenFlow + xray routing brain.
//!
//! Reads the canonical subid registry from `/etc/ghostbridge/subid-registry.json`
//! and writes two tmpfs artifacts:
//!   - `/dev/shm/xray-routes.json`    — routes for the op-identity-shuttle
//!   - `/dev/shm/openflow-routes.json` — rules for the OpenFlow controller
//!
//! Per AGENTS.md §4: D-Bus is the control plane; Gemma is a host service that
//! produces structured state, not a CLI bypass. It never shells out to network
//! tools. OpenFlow rules may be applied via D-Bus by a separate controller.

mod ui_gallery;

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::path::Path;
use tracing::{info, warn};

const SUBID_REGISTRY: &str = "/etc/ghostbridge/subid-registry.json";
const XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";
const OPENFLOW_ROUTES: &str = "/dev/shm/openflow-routes.json";

#[derive(Debug, Clone, Deserialize, Serialize)]
struct SubidRegistry {
    version: u32,
    entries: Vec<RegistryEntry>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct RegistryEntry {
    uuid: String,
    subid: String,
    #[serde(rename = "category")]
    category: String,
    #[serde(rename = "component_type")]
    component_type: String,
    subject: String,
    verb: String,
    version: u8,
    tags: Vec<String>,
    subdomains: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    gemma: Option<GemmaConfig>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct GemmaConfig {
    backend: BackendSpec,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(tag = "type")]
enum BackendSpec {
    #[serde(rename = "ingress")]
    Ingress,
    #[serde(rename = "tcp")]
    Tcp { host: String, port: u16 },
    #[serde(rename = "grpc")]
    Grpc {
        host: String,
        port: u16,
        #[serde(rename = "service_name")]
        service_name: String,
    },
    #[serde(rename = "unix")]
    Unix { path: String },
    #[serde(rename = "dns")]
    Dns { host: String, port: u16 },
    /// Internal metadata entry — not xray-routable, produces no outbound.
    #[serde(rename = "file")]
    File {
        #[allow(dead_code)]
        path: String,
    },
    /// Internal service — not xray-routable, produces no outbound.
    #[serde(rename = "internal")]
    Internal,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoutingMap {
    version: u32,
    xray_routes: Vec<XrayRoute>,
    openflow_rules: Vec<OpenFlowRule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoute {
    tag: String,
    subdomains: Vec<String>,
    backend: BackendSpec,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OpenFlowRule {
    priority: u16,
    #[serde(rename = "match_fields")]
    match_fields: HashMap<String, String>,
    actions: Vec<String>,
    description: Option<String>,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Gemma routing brain starting");

    let registry = load_registry()?;
    let routes = derive_routes(&registry);

    write_json(XRAY_ROUTES, &routes)?;
    write_json(OPENFLOW_ROUTES, &routes)?;

    info!(
        xray_routes = routes.xray_routes.len(),
        openflow_rules = routes.openflow_rules.len(),
        "Gemma wrote routing artifacts"
    );

    // Generate the json-render.dev UI spec gallery via Gemma model inference
    // over the live sealed-blob catalog (tops up toward the target count).
    if let Err(e) = ui_gallery::generate_gallery() {
        warn!("Gemma UI gallery generation failed: {e}");
    }

    Ok(())
}

fn load_registry() -> Result<SubidRegistry> {
    let raw = fs::read_to_string(SUBID_REGISTRY)
        .with_context(|| format!("failed to read subid registry: {SUBID_REGISTRY}"))?;
    let parsed: SubidRegistry =
        serde_json::from_str(&raw).with_context(|| "failed to parse subid registry as JSON")?;
    Ok(parsed)
}

fn derive_routes(registry: &SubidRegistry) -> XrayRoutingMap {
    let mut xray_routes = Vec::new();
    let mut openflow_rules = default_privacy_chain();

    for entry in &registry.entries {
        let Some(gemma) = &entry.gemma else { continue };

        // Skip non-routable backends — they are metadata (schema files,
        // internal services) that should not produce xray outbounds.
        if matches!(
            gemma.backend,
            BackendSpec::File { .. } | BackendSpec::Internal
        ) {
            continue;
        }

        let tag = entry
            .tags
            .first()
            .cloned()
            .unwrap_or_else(|| entry.subject.clone());

        // Skip duplicate tags — first declaration wins.
        if xray_routes.iter().any(|r: &XrayRoute| r.tag == tag) {
            continue;
        }

        let route = XrayRoute {
            tag: tag.clone(),
            subdomains: entry.subdomains.clone(),
            backend: gemma.backend.clone(),
        };
        xray_routes.push(route);

        if let Some(rule) = backend_to_openflow_rule(&tag, &gemma.backend) {
            openflow_rules.push(rule);
        }
    }

    XrayRoutingMap {
        version: 1,
        xray_routes,
        openflow_rules,
    }
}

/// Default privacy chain flows for the GhostBridge OVS bridge.
/// These match the conventions in `crates/op-plugins/src/state_plugins/privacy_router.rs`.
fn default_privacy_chain() -> Vec<OpenFlowRule> {
    vec![
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_wg".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_wg -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_warp".to_string())]),
            actions: vec!["output:gbr_xray".to_string()],
            description: Some("gbr_warp -> gbr_xray".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_xray".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_xray -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 200,
            match_fields: HashMap::from([("dl_type".to_string(), "0x0806".to_string())]),
            actions: vec!["arp_responder".to_string()],
            description: Some("ARP Responder for privacy network".to_string()),
        },
    ]
}

/// Translate a Gemma backend into an OpenFlow rule for the bridge.
/// Only TCP/GRPC backends produce IP/Port matchable rules here; Unix sockets
/// route through the tonic-web gRPC bridge (reflection demuxes) so no OVS
/// bridge match is needed.
fn backend_to_openflow_rule(tag: &str, backend: &BackendSpec) -> Option<OpenFlowRule> {
    let (host, port) = match backend {
        BackendSpec::Tcp { host, port } => (host.clone(), *port),
        BackendSpec::Grpc { host, port, .. } => (host.clone(), *port),
        BackendSpec::Ingress
        | BackendSpec::Unix { .. }
        | BackendSpec::Dns { .. }
        | BackendSpec::File { .. }
        | BackendSpec::Internal => return None,
    };

    let mut match_fields = HashMap::new();
    match_fields.insert("dl_type".to_string(), "0x0800".to_string());
    match_fields.insert("nw_proto".to_string(), "6".to_string()); // TCP
    match_fields.insert("nw_dst".to_string(), host.clone());
    match_fields.insert("tp_dst".to_string(), port.to_string());

    Some(OpenFlowRule {
        priority: 150,
        match_fields,
        actions: vec!["output:ovsbr0-mgmt".to_string()],
        description: Some(format!("Gemma: {tag} -> host backend {host}:{port}")),
    })
}

fn write_json<P: AsRef<Path>>(path: P, value: &XrayRoutingMap) -> Result<()> {
    let tmp = format!("{}.tmp", path.as_ref().display());
    let mut f =
        fs::File::create(&tmp).with_context(|| format!("failed to create tmp file: {tmp}"))?;
    let json =
        serde_json::to_string_pretty(value).with_context(|| "failed to serialize routing map")?;
    f.write_all(json.as_bytes())
        .with_context(|| format!("failed to write tmp file: {tmp}"))?;
    f.sync_data()
        .with_context(|| format!("failed to sync tmp file: {tmp}"))?;
    fs::rename(&tmp, path.as_ref())
        .with_context(|| format!("failed to rename {tmp} to {}", path.as_ref().display()))?;
    Ok(())
}

//! Gemma UI Gallery Generator — real model inference (no hardcoded specs).
//!
//! Feeds the live sealed-blob catalog plus the official json-render.dev authoring
//! reference to the Gemma model (via Ollama) under a single meta-prompt:
//! "make this data accessible to as many people, industries, use cases, and
//! causes as possible". The model emits json-render specs; we extract them,
//! de-duplicate by structural signature, and top the gallery up to TARGET_COUNT.
//!
//! Output: `/dev/shm/gemma-ui-specs.json` — the same file op-web's `/api/gemma/*`
//! endpoints read and write. There is no dead schema file and no static specs;
//! the sealed blob catalog is the only source of truth for what gets rendered.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashSet;
use std::fs;
use std::io::Write;
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use tracing::{info, warn};

const GEMMA_UI_SPECS: &str = "/dev/shm/gemma-ui-specs.json";
const TARGET_COUNT: usize = 1000;
const MAX_ATTEMPTS: usize = 4000;
const SPECS_PER_BATCH: usize = 8;

/// The json-render component catalog. A spec is only renderable if EVERY element
/// `type` is one of these — the frontend registry implements exactly this set,
/// and json-render will not render a `type` absent from its catalog. Specs that
/// reference anything else are dropped at generation time.
const ALLOWED_COMPONENTS: &[&str] = &[
    "container",
    "card",
    "kv",
    "heading",
    "text",
    "badge",
    "row",
    "code",
];

/// Audiences that drive spec diversity — one per batch, rotated so the gallery
/// spans "as many people, industries, and use cases as possible".
const AUDIENCES: &[&str] = &[
    "systems administrators",
    "security auditors",
    "network engineers",
    "healthcare operators",
    "educators and students",
    "small-business owners",
    "journalists and researchers",
    "accessibility-first users",
    "field technicians",
    "financial compliance officers",
    "non-profit and humanitarian operators",
    "data scientists",
    "on-call SREs",
    "executives wanting a glanceable overview",
    "developers debugging live state",
    "privacy-conscious end users",
];

const META_PROMPT: &str = "Make this data (every sealed plugin blob shown above) \
accessible to as many people, industries, use cases, and causes as possible. \
Design distinct, genuinely useful json-render UI panels that surface the REAL \
plugin fields for the target audience.";

const AUTHORING_INSTRUCTIONS: &str = "## Output rules\n\
- Emit EXACTLY {N} DISTINCT json-render specs, each in its own fenced block tagged `json-render`.\n\
- Each block MUST be valid JSON with a `root` (string) and an `elements` (object).\n\
- Use ONLY these component types: container, card, kv, heading, text, badge, row, code.\n\
- Reference REAL plugin and field names from the blob context above — never placeholders.\n\
- Vary the layout and which plugins you feature so no two specs are structurally identical.";

// ── Types (mirror op-web's gemma store format) ────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecEntry {
    pub id: String,
    pub spec: Value,
    pub prompt: String,
    pub tags: Vec<String>,
    pub created_at: u64,
    pub signature: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecGallery {
    pub version: u32,
    pub specs: Vec<GemmaSpecEntry>,
}

impl Default for GemmaSpecGallery {
    fn default() -> Self {
        Self {
            version: 1,
            specs: vec![],
        }
    }
}

// ── Ollama wire types ─────────────────────────────────────────────────────────

#[derive(Serialize)]
struct ChatMsg<'a> {
    role: &'a str,
    content: &'a str,
}

#[derive(Serialize)]
struct ChatReq<'a> {
    model: String,
    stream: bool,
    messages: Vec<ChatMsg<'a>>,
}

#[derive(Deserialize)]
struct ChatResp {
    message: ChatRespMsg,
}

#[derive(Deserialize)]
struct ChatRespMsg {
    #[serde(default)]
    content: String,
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn signature(elements: &Value) -> String {
    let bytes = serde_json::to_vec(elements).unwrap_or_default();
    hex::encode(&blake3::hash(&bytes).as_bytes()[..8])
}

fn model() -> String {
    std::env::var("GEMMA_MODEL").unwrap_or_else(|_| "gemma4:e4b".to_string())
}

fn base_url() -> String {
    std::env::var("OLLAMA_BASE_URL").unwrap_or_else(|_| "http://127.0.0.1:11434".to_string())
}

fn ollama_chat(client: &reqwest::blocking::Client, system: &str, user: &str) -> Result<String> {
    let body = ChatReq {
        model: model(),
        stream: false,
        messages: vec![
            ChatMsg {
                role: "system",
                content: system,
            },
            ChatMsg {
                role: "user",
                content: user,
            },
        ],
    };
    let resp = client
        .post(format!("{}/api/chat", base_url()))
        .json(&body)
        .send()
        .context("ollama request failed")?;
    if !resp.status().is_success() {
        anyhow::bail!("ollama HTTP {}", resp.status());
    }
    let parsed: ChatResp = resp.json().context("ollama response parse failed")?;
    Ok(parsed.message.content)
}

/// True iff the spec is structurally sound AND every element `type` is in the
/// json-render catalog (`ALLOWED_COMPONENTS`) and every child reference resolves.
fn spec_is_catalog_valid(v: &Value) -> bool {
    let Some(root) = v.get("root").and_then(Value::as_str) else {
        return false;
    };
    let Some(elements) = v.get("elements").and_then(Value::as_object) else {
        return false;
    };
    if elements.is_empty() || !elements.contains_key(root) {
        return false;
    }
    for el in elements.values() {
        let Some(ty) = el.get("type").and_then(Value::as_str) else {
            return false;
        };
        if !ALLOWED_COMPONENTS.contains(&ty) {
            return false;
        }
        if let Some(children) = el.get("children").and_then(Value::as_array) {
            for child in children {
                match child.as_str() {
                    Some(key) if elements.contains_key(key) => {}
                    _ => return false,
                }
            }
        }
    }
    true
}

/// Extract every ```json-render ... ``` block, keeping only well-formed,
/// non-duplicate specs (relative to `used` and to the current batch).
fn extract_specs(text: &str, prompt: &str, used: &HashSet<String>) -> Vec<GemmaSpecEntry> {
    let mut out: Vec<GemmaSpecEntry> = Vec::new();
    let mut remaining = text;
    while let Some(start) = remaining.find("```json-render") {
        let after = &remaining[start + 14..];
        let content_start = after.find('\n').map(|i| i + 1).unwrap_or(0);
        let content = &after[content_start..];
        let Some(end) = content.find("\n```") else {
            break;
        };
        let block = content[..end].trim();
        if let Ok(v) = serde_json::from_str::<Value>(block) {
            if spec_is_catalog_valid(&v) {
                let elements = v.get("elements").cloned().unwrap_or(Value::Null);
                let sig = signature(&elements);
                let dup_here = out.iter().any(|e| e.signature == sig);
                if !used.contains(&sig) && !dup_here {
                    out.push(GemmaSpecEntry {
                        id: format!("spec-{sig}"),
                        spec: v,
                        prompt: prompt.to_string(),
                        tags: vec![],
                        created_at: now_secs(),
                        signature: sig,
                    });
                }
            }
        }
        remaining = &content[end + 4..];
    }
    out
}

fn load_existing() -> GemmaSpecGallery {
    match fs::read(GEMMA_UI_SPECS) {
        Ok(bytes) => serde_json::from_slice(&bytes).unwrap_or_default(),
        Err(_) => GemmaSpecGallery::default(),
    }
}

fn write_gallery(gallery: &GemmaSpecGallery) -> Result<()> {
    let tmp = format!("{GEMMA_UI_SPECS}.tmp");
    let mut f = fs::File::create(&tmp).with_context(|| format!("create {tmp}"))?;
    f.write_all(&serde_json::to_vec_pretty(gallery)?)
        .with_context(|| format!("write {tmp}"))?;
    f.sync_data().with_context(|| format!("sync {tmp}"))?;
    drop(f);
    fs::rename(&tmp, GEMMA_UI_SPECS)
        .with_context(|| format!("rename {tmp} -> {GEMMA_UI_SPECS}"))?;
    Ok(())
}

// ── Public API ────────────────────────────────────────────────────────────────

/// Generate (or top up) the UI spec gallery to TARGET_COUNT entries via real
/// Gemma inference over the live sealed-blob catalog. Idempotent and additive:
/// existing specs are kept, new non-duplicate specs are appended.
pub fn generate_gallery() -> Result<()> {
    let mut gallery = load_existing();
    let mut used: HashSet<String> = gallery.specs.iter().map(|s| s.signature.clone()).collect();

    if gallery.specs.len() >= TARGET_COUNT {
        info!(
            count = gallery.specs.len(),
            "Gemma UI gallery already at target — nothing to do"
        );
        return Ok(());
    }

    let shm = op_gemma::build_shm_context();
    let system = format!(
        "{}\n\n---\n\n{}\n\n---\n\n{}",
        op_gemma::JSON_RENDER_REFERENCE,
        shm,
        AUTHORING_INSTRUCTIONS.replace("{N}", &SPECS_PER_BATCH.to_string()),
    );

    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(180))
        .build()
        .context("build reqwest client")?;

    info!(
        model = %model(),
        base_url = %base_url(),
        existing = gallery.specs.len(),
        target = TARGET_COUNT,
        "Gemma UI gallery: starting model-driven generation"
    );

    let mut attempts = 0usize;
    while gallery.specs.len() < TARGET_COUNT && attempts < MAX_ATTEMPTS {
        let audience = AUDIENCES[attempts % AUDIENCES.len()];
        let user = format!(
            "{META_PROMPT}\n\nTarget audience for THIS batch: {audience}.\n\
             Produce {SPECS_PER_BATCH} new specs that differ from anything obvious."
        );
        attempts += 1;

        match ollama_chat(&client, &system, &user) {
            Ok(text) => {
                let specs = extract_specs(&text, &user, &used);
                if specs.is_empty() {
                    warn!(attempt = attempts, "batch produced no new usable specs");
                    continue;
                }
                for s in specs {
                    if gallery.specs.len() >= TARGET_COUNT {
                        break;
                    }
                    used.insert(s.signature.clone());
                    gallery.specs.push(s);
                }
                if attempts.is_multiple_of(5) {
                    let _ = write_gallery(&gallery);
                }
                info!(
                    count = gallery.specs.len(),
                    target = TARGET_COUNT,
                    "Gemma UI gallery progress"
                );
            }
            Err(e) => {
                warn!("ollama batch failed (attempt {attempts}): {e}");
                // If nothing has been produced after a few tries, Ollama is
                // almost certainly unreachable — stop rather than spin.
                if gallery.specs.is_empty() && attempts >= 3 {
                    warn!("giving up: ollama unavailable after {attempts} attempts");
                    break;
                }
            }
        }
    }

    write_gallery(&gallery)?;
    info!(
        count = gallery.specs.len(),
        attempts, "Gemma UI gallery written"
    );
    Ok(())
}

//! SHM blob context builder for the Gemma system prompt.

use op_blob::catalog::ActiveReflectionCatalog;
use serde_json::json;
use std::io;
use tracing::warn;

/// Build a compact context string describing the current live SHM blob state.
/// Always returns a valid string — never panics, never propagates I/O errors.
pub fn build_shm_context() -> String {
    match ActiveReflectionCatalog::open_shm() {
        Err(e) if e.kind() == io::ErrorKind::NotFound => "## Active Plugin Blobs\n\
             No blobs sealed. The opdbus plugin daemon may not be running.\n"
            .to_string(),
        Err(e) => {
            warn!("shm_context: failed to open blob catalog: {e}");
            "## Active Plugin Blobs\n\
             Blob catalog unavailable (read error — check op-blob logs).\n"
                .to_string()
        }
        Ok(catalog) => build_from_catalog(&catalog),
    }
}

fn build_from_catalog(catalog: &ActiveReflectionCatalog) -> String {
    let blobs: Vec<serde_json::Value> = catalog
        .plugin_object_blobs()
        .into_iter()
        .map(|blob| {
            let fields: Vec<String> = serde_json::from_str::<serde_json::Value>(&blob.schema_json)
                .ok()
                .and_then(|v| {
                    v.get("properties")
                        .or_else(|| v.get("fields"))
                        .and_then(|f| f.as_object())
                        .map(|obj| obj.keys().cloned().collect())
                })
                .unwrap_or_default();

            let hash = &blob.manifest.schema_hash;
            let short_hash = &hash[..16.min(hash.len())];
            json!({
                "plugin": blob.manifest.plugin_id,
                "hash":   short_hash,
                "fields": fields,
            })
        })
        .collect();

    let sealed_count = blobs.len();
    let context_json = json!({ "blobs": blobs, "sealed_count": sealed_count });

    format!(
        "## Active Plugin Blobs (live SHM state)\n\
        {}\n\n\
        ### Rendering conventions:\n\
        - String fields → `kv` element with kind \"string\"\n\
        - Integer/number fields → `kv` element with kind \"number\"\n\
        - Boolean fields → `kv` element with kind \"boolean\"\n\
        - Running/active/sealed → `badge` with tone \"ok\"\n\
        - Stopped/error/missing → `badge` with tone \"danger\"\n\
        - Group plugin fields in a `card` with title = plugin name\n",
        serde_json::to_string_pretty(&context_json).unwrap_or_default()
    )
}

//! op-gemma library interface.
//!
//! Exposes `build_shm_context()` and `JSON_RENDER_REFERENCE` for use by
//! `op-web`'s Gemma chat handler.

pub mod shm_context;

pub use shm_context::build_shm_context;

/// The complete json-render.dev authoring reference, embedded at compile time.
/// Used verbatim in both the Gemma system prompt and the
/// `GET /api/gemma/json-render-docs` endpoint so they are always identical.
pub const JSON_RENDER_REFERENCE: &str = include_str!("json_render_reference.md");

[package]
name = "op-gemma"
version.workspace = true
edition.workspace = true
authors.workspace = true
license.workspace = true
description = "Gemma routing brain — subid → tag → xray + OpenFlow rules"

[lib]
name = "op_gemma"
path = "src/lib.rs"

[[bin]]
name = "op-gemma"
path = "src/main.rs"

[dependencies]
op-blob = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
anyhow = { workspace = true }
tracing = { workspace = true }
tracing-subscriber = { workspace = true }
reqwest = { version = "0.11", features = ["json", "blocking"] }
blake3 = "1.5"
hex = { workspace = true }

//! Axum handlers for `/api/gemma/*`.
//!
//! Provides:
//!   POST   /api/gemma/chat                 — SSE stream to Ollama
//!   GET    /api/gemma/gallery              — list generated specs
//!   POST   /api/gemma/gallery              — append specs
//!   DELETE /api/gemma/gallery/:id          — remove spec
//!   GET    /api/gemma/catalog              — list promoted entries
