// ── POST /api/gemma/catalog/promote/:id ──────────────────────────────────────

pub async fn catalog_promote(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    // Always acquire gallery lock first, then catalog — consistent order prevents deadlock.
    let _glock = state.gemma_gallery_lock.lock().await;
    let _clock = state.gemma_catalog_lock.lock().await;

    let mut gallery = match store::read_gallery() {
        Ok(g) => g,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let idx = gallery.specs.iter().position(|s| s.id == id);
    let Some(idx) = idx else {
        return StatusCode::NOT_FOUND.into_response();
    };

    let spec = gallery.specs.remove(idx);
    catalog.entries.push(GemmaCatalogEntry {
        base: spec,
        promoted_at: now_secs(),
        label: None,
    });

    if let Err(e) = store::write_gallery(&gallery) {
        return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response();
    }
    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::OK.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── DELETE /api/gemma/catalog/:id ────────────────────────────────────────────

pub async fn catalog_delete(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    let _lock = state.gemma_catalog_lock.lock().await;
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let before = catalog.entries.len();
    catalog.entries.retain(|e| e.base.id != id);
    if catalog.entries.len() == before {
        return StatusCode::NOT_FOUND.into_response();
    }

    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::NO_CONTENT.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── PATCH /api/gemma/catalog/:id ─────────────────────────────────────────────

pub async fn catalog_update(
    State(state): State<Arc<AppState>>,
    Path(id): Path<String>,
    Json(req): Json<CatalogUpdateRequest>,
) -> impl IntoResponse {
    let _lock = state.gemma_catalog_lock.lock().await;
    let mut catalog = match store::read_catalog() {
        Ok(c) => c,
        Err(e) => return (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    };

    let entry = catalog.entries.iter_mut().find(|e| e.base.id == id);
    let Some(entry) = entry else {
        return StatusCode::NOT_FOUND.into_response();
    };

    if let Some(label) = req.label {
        entry.label = Some(label);
    }
    if let Some(tags) = req.tags {
        entry.base.tags = tags;
    }

    match store::write_catalog(&catalog) {
        Ok(()) => StatusCode::OK.into_response(),
        Err(e) => (StatusCode::INTERNAL_SERVER_ERROR, e.to_string()).into_response(),
    }
}

// ── GET /api/gemma/plugin-schema/:plugin ─────────────────────────────────────

/// Return a plugin's sealed-blob schema as JSON so the UI can render it via
/// json-render. The sealed blob catalog is the source of render truth.
pub async fn plugin_schema(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    use op_blob::catalog::ActiveReflectionCatalog;
    let target = plugin.to_lowercase().replace('-', "_");
    match ActiveReflectionCatalog::open_shm() {
        Ok(catalog) => {
            let found = catalog
                .plugin_object_blobs()
                .into_iter()
                .find(|b| b.manifest.plugin_id == target);
            match found {
                Some(b) => {
                    let schema: serde_json::Value =
                        serde_json::from_str(&b.schema_json).unwrap_or(serde_json::Value::Null);
                    Json(serde_json::json!({
                        "plugin": b.manifest.plugin_id,
                        "schema_hash": b.manifest.schema_hash,
                        "schema": schema,
                    }))
                    .into_response()
                }
                None => (
                    StatusCode::NOT_FOUND,
                    format!("no sealed blob for plugin '{target}'"),
                )
                    .into_response(),
            }
        }
        Err(e) => (
            StatusCode::SERVICE_UNAVAILABLE,
            format!("blob catalog unavailable: {e}"),
        )
            .into_response(),
    }
}

// ── GET /api/gemma/json-render-docs ──────────────────────────────────────────

pub async fn json_render_docs() -> impl IntoResponse {
    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/markdown; charset=utf-8"),
    );
    (headers, op_gemma::JSON_RENDER_REFERENCE)
}

// ── GET /api/gemma/plugin-proto/:plugin ───────────────────────────────────────

/// Generate a plugin's gRPC proto as TEXT for TypeScript/protobuf-ts codegen.
/// Reads the sealed blob from SHM, reconstructs proto definitions from the schema.
/// Covers dynamically-registered plugins that have no static .proto files.
pub async fn plugin_proto(
    State(_state): State<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> impl IntoResponse {
    let target = plugin.to_lowercase().replace('-', "_");

    // Read schema from SHM blob
    let schema = match op_blob::catalog::read_plugin_schema_shm(&target) {
        Some(s) => s,
        None => {
            return (
                StatusCode::NOT_FOUND,
                format!("no sealed blob for plugin '{target}'"),
            )
                .into_response();
        }
    };

    // Generate text proto from schema
    let proto = generate_plugin_method_protos(&target, &schema);

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    (headers, proto).into_response()
}

// ── GET /api/gemma/all-plugin-protos ───────────────────────────────────────────

/// Generate text protos for ALL active plugins in the SHM catalog.
/// Produces a unified proto file covering all dynamically-registered methods.
/// For Lovable: fetch this endpoint and use with protoc-ts.
pub async fn all_plugin_protos(
    State(_state): State<Arc<AppState>>,
) -> impl IntoResponse {
    let plugin_ids = match op_blob::catalog::read_manifest_plugin_ids_shm() {
        Some(ids) => ids,
        None => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                "blob catalog unavailable",
            )
                .into_response();
        }
    };

    let mut combined = String::new();
    combined.push_str("syntax = \"proto3\";\n\n");
    combined.push_str("package operation.plugin.v1;\n\n");
    combined.push_str("import \"google/protobuf/struct.proto\";\n\n");

    for plugin_id in plugin_ids {
        if let Some(schema) = op_blob::catalog::read_plugin_schema_shm(&plugin_id) {
            let proto = generate_plugin_method_protos(&plugin_id, &schema);
            combined.push_str(&proto);
        }
    }

    let mut headers = HeaderMap::new();
    headers.insert(
        axum::http::header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    (headers, combined).into_response()
}

//! Shared types for the Gemma chat, gallery, and catalog handlers.

use serde::{Deserialize, Serialize};

// ── Chat session types ──────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaChatMessage {
    pub role: String, // "system" | "user" | "assistant"
    pub content: String,
}

#[derive(Debug)]
pub struct GemmaSession {
    pub messages: Vec<GemmaChatMessage>,
    pub last_active: std::time::Instant,
}

// ── Chat request/response ───────────────────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct GemmaChatRequest {
    pub message: String,
    pub session_id: String,
}

// ── Spec / gallery / catalog ────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecEntry {
    pub id: String,
    pub spec: serde_json::Value, // { root: String, elements: Map }
    pub prompt: String,
    pub tags: Vec<String>,
    pub created_at: u64,   // unix seconds
    pub signature: String, // blake3 16-char hex prefix of elements JSON
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecGallery {
    pub version: u32,
    pub specs: Vec<GemmaSpecEntry>,
}

impl Default for GemmaSpecGallery {
    fn default() -> Self {
        Self {
            version: 1,
            specs: vec![],
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaCatalogEntry {
    #[serde(flatten)]
    pub base: GemmaSpecEntry,
    pub promoted_at: u64,
    pub label: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaCatalog {
    pub version: u32,
    pub entries: Vec<GemmaCatalogEntry>,
}

impl Default for GemmaCatalog {
    fn default() -> Self {
        Self {
            version: 1,
