//! OCI Generative AI Agent backend for UI-spec generation.
//!
//! Temporary replacement for the local Gemma/Ollama model: UI generation calls
//! the configured OCI GenAI Agent endpoint via the `oci` CLI. Only the inference
//! transport changes here — prompt construction and json-render spec extraction
//! remain unchanged in the callers.

use anyhow::{Context, Result};
use serde_json::Value;
use std::process::Command;

/// Default agent endpoint. Override with `OCI_AGENT_ENDPOINT_ID`.
const DEFAULT_ENDPOINT_ID: &str =
    "ocid1.genaiagentendpoint.oc1.iad.amaaaaaa2be5t4yajrx4qdqrtcmqtsezzzhf35zeqeznwat2xdatq266m6ua";

pub fn endpoint_id() -> String {
    std::env::var("OCI_AGENT_ENDPOINT_ID").unwrap_or_else(|_| DEFAULT_ENDPOINT_ID.to_string())
}

fn oci_bin() -> String {
    std::env::var("OCI_BIN").unwrap_or_else(|_| "oci".to_string())
}

/// Send a single-turn message to the OCI GenAI Agent endpoint and return the
/// agent's text response. Blocking — shells out to the `oci` CLI, which handles
/// OCI request signing via `~/.oci/config`.
pub fn agent_chat_blocking(message: &str) -> Result<String> {
    let output = Command::new(oci_bin())
        .args([
            "generative-ai-agent-runtime",
            "agent-endpoint",
            "chat",
            "--agent-endpoint-id",
            &endpoint_id(),
            "--should-stream",
            "false",
            "--output",
            "json",
            "--user-message",
            message,
        ])
        .output()
        .context("failed to invoke `oci` CLI")?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        anyhow::bail!("oci agent chat failed ({}): {}", output.status, stderr.trim());
    }

    let parsed: Value =
        serde_json::from_slice(&output.stdout).context("failed to parse oci chat JSON output")?;

    parsed
        .pointer("/data/message/content/text")
        .and_then(Value::as_str)
        .map(str::to_string)
        .context("oci chat response missing data.message.content.text")
}

