}

fn ollama_chat(client: &reqwest::blocking::Client, system: &str, user: &str) -> Result<String> {
    let body = ChatReq {
        model: model(),
        stream: false,
        messages: vec![
            ChatMsg {
                role: "system",
                content: system,
            },
            ChatMsg {
                role: "user",
                content: user,
            },
        ],
    };
    let resp = client
        .post(format!("{}/api/chat", base_url()))
        .json(&body)
        .send()
        .context("ollama request failed")?;
    if !resp.status().is_success() {
        anyhow::bail!("ollama HTTP {}", resp.status());
    }
    let parsed: ChatResp = resp.json().context("ollama response parse failed")?;
    Ok(parsed.message.content)
}

