pub async fn chat_stream(
    State(state): State<Arc<AppState>>,
    Json(req): Json<GemmaChatRequest>,
) -> impl IntoResponse {
    // Sweep expired sessions (30 min TTL).
    let ttl = Duration::from_secs(1800);
    state
        .gemma_sessions
        .retain(|_, v| v.last_active.elapsed() < ttl);

    // Load or create session history.
    let history: Vec<GemmaChatMessage> = state
        .gemma_sessions
        .get(&req.session_id)
        .map(|s| s.messages.clone())
        .unwrap_or_default();

    // Build system prompt.
    let shm_ctx = op_gemma::build_shm_context();
    let system_prompt = format!(
        "{}\n\n---\n\n{}\n\n---\n\n{}",
        op_gemma::JSON_RENDER_REFERENCE,
        shm_ctx,
        AUTHORING_INSTRUCTIONS,
    );

    // The OCI agent takes a single message, so fold the system prompt, the last
    // 49 history turns, and the new user message into one prompt.
    let tail = if history.len() > 49 {
        &history[history.len() - 49..]
    } else {
        &history[..]
    };
    let mut convo = String::new();
    for m in tail {
        convo.push_str(&format!("[{}] {}\n", m.role, m.content));
    }
    let agent_message = format!(
        "{system_prompt}\n\n---\n\nConversation so far:\n{convo}[user] {}",
        req.message
    );

    info!("gemma: querying OCI agent for session {}", req.session_id);

    let (tx, rx) = mpsc::channel::<Result<Event, Infallible>>(64);
    let session_id = req.session_id.clone();
    let user_message = req.message.clone();
    let sessions = Arc::clone(&state.gemma_sessions);

    tokio::spawn(async move {
        let result =
            tokio::task::spawn_blocking(move || op_gemma::oci::agent_chat_blocking(&agent_message))
                .await;

        let full = match result {
            Ok(Ok(text)) => text,
            Ok(Err(e)) => {
                let msg = format!("OCI agent chat failed: {e}");
                warn!("{msg}");
                let _ = tx
                    .send(Ok(
                        Event::default().data(serde_json::json!({"error": msg}).to_string())
                    ))
                    .await;
                return;
            }
            Err(e) => {
                let msg = format!("OCI agent task join failed: {e}");
                warn!("{msg}");
                let _ = tx
                    .send(Ok(
                        Event::default().data(serde_json::json!({"error": msg}).to_string())
                    ))
                    .await;
                return;
            }
        };

        // Emit the full response as a single delta, then the terminal event
        // carrying the extracted json-render specs.
        let _ = tx
            .send(Ok(
                Event::default().data(serde_json::json!({"delta": full}).to_string())
            ))
            .await;

        let specs = extract_specs(&full, &user_message);
        let done_evt = serde_json::json!({
            "done": true,
            "full": full,
            "specs": specs,
        });
        let _ = tx
            .send(Ok(Event::default().data(done_evt.to_string())))
            .await;

        // Persist to session.
        let mut entry = sessions
            .entry(session_id.clone())
            .or_insert_with(|| GemmaSession {
                messages: vec![],
                last_active: std::time::Instant::now(),
            });
        entry.messages.push(GemmaChatMessage {
            role: "user".into(),
            content: user_message.clone(),
        });
        entry.messages.push(GemmaChatMessage {
            role: "assistant".into(),
            content: full.clone(),
        });
        entry.last_active = std::time::Instant::now();
    });

    sse_stream(rx).keep_alive(KeepAlive::new().interval(Duration::from_secs(15)))
}

