/// Generate one valid single-package proto file per method.
///
/// Unlike [`generate_plugin_method_protos`] (which concatenates every method
/// into a single multi-`package` string that `protoc` rejects), this returns
/// `(file_name, contents)` pairs where each file is independently compilable.
/// File names follow the UI codegen convention
/// `<plugin>__operation_method_<plugin>_<method>.proto`.
pub fn generate_plugin_method_protos_split(
    plugin_id: &str,
    schema: &PluginSchema,
) -> Vec<(String, String)> {
    let plugin_ident = sanitize_proto_ident(plugin_id).to_lowercase();
    let mut files = Vec::with_capacity(schema.methods.len());
    for (method_name, method_decl) in &schema.methods {
        let package = method_package(plugin_id, method_name);
        let file_name = format!("{}__{}.proto", plugin_ident, package.replace('.', "_"));
        files.push((file_name, generate_method_proto(plugin_id, method_name, method_decl)));
    }
    files
}

